import * as C from "/store-orders/core.js?v=20261031-store-orders-r28";
import {VersionGuard} from "/store-orders/runtime.js?v=20261031-store-orders-r28";
import {validateExtraction,extractionOrder,evaluateExtraction,fullOrderChecks} from "/store-orders/recognition.js?v=20261031-store-orders-r28";
const $=id=>document.getElementById(id),guard=new VersionGuard();let master=null,image=null,cropData="",raw=null,expected=null,config=null,busy=false,previewUrl="",provenance="",syntheticImage="",prepared=null,recognition=null,profileUI=null;
const review=createReview($("paper-review"),{requireVersion:async()=>{try{await guard.require();}finally{controls();}},exportProfile:()=>profileUI?.get()??($("pos-format")?.value==="legacy"?null:{}),context:()=>({existingNumbers:$("existing-numbers").value.split(/[,，、\s]+/).filter(Boolean)})});
profileUI=createPOSProfile($("pos-template-panel"),{requireVersion:()=>guard.require(),onChange:()=>review.refresh()});
const mode=()=>$("mode").value;
const consent=()=>mode()==="full"?$("synthetic-confirmed").checked:$("deidentified").checked;
function status(text,error=false){$("status").textContent=text;$("status").className=error?"error":"success";}
async function run(work){if(busy)return;busy=true;controls();try{await guard.require();await work();}catch(e){status(e.message,true);}finally{busy=false;controls();}}
function controls(){const blocked=guard.blocked||busy;profileUI?.setBlocked(blocked);for(const id of ["crop","synthetic","master","image","result-file","expected","left","right","top","bottom","deidentified","synthetic-confirmed","mode","expected-store","existing-numbers","synthetic-image"])$(id).disabled=blocked;$("recognize").disabled=blocked||!cropData||!consent()||!config?.ready;$("download-image").disabled=blocked||!syntheticImage;$("download").disabled=blocked||!raw;$("version-warning").hidden=!guard.blocked;if(guard.blocked)$("paper-review").querySelectorAll("[data-export]").forEach(b=>b.disabled=true);}
function clearCrop(){cropData="";prepared=null;$("deidentified").checked=false;$("synthetic-confirmed").checked=false;$("crop-preview").hidden=true;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl="";controls();}
function clearResults(){review.clear();raw=null;recognition=null;$("results").replaceChildren();$("summary").textContent="";$("metrics").textContent="";controls();}
function el(tag,value,cls){const e=document.createElement(tag);e.textContent=value||"";if(cls)e.className=cls;return e;}
function render(){if(!raw)return;if(!raw.header)$("raw-results").open=true;review.update(raw,master,mode()==="full"&&["left","top"].every(id=>Number($(id).value)===0)&&["right","bottom"].every(id=>Number($(id).value)===100)?cropData:"",recognition);const order=extractionOrder(raw,master);$("results").replaceChildren();if(raw.header){const h=raw.header,check=fullOrderChecks(raw,{expectedStore:$("expected-store").value.trim().toUpperCase(),existingNumbers:$("existing-numbers").value.split(/[,，、\s]+/).filter(Boolean)}),box=el("div","","item");box.append(el("h3","完整單表頭（虛構資料）"));for(const [label,value] of [["訂單編號",h.paperNumber],["門市代號",h.storeCode],["紙本日期",h.businessDate],["轉換業務日期",check.normalizedDate],["經手人",h.clerk],["頁碼",`${h.pageNumber??"?"}／${h.pageCount??"?"}`],["整單商品列數",h.paperRowCount??"未填"],["測試姓名",h.customer.name],["測試電話（保留原字串）",h.customer.phone],["測試地址",h.customer.address],["備註",h.note],["成交總額",raw.paperTotal??"未讀出"]])box.append(el("p",`${label}：${value||"未填／不明"}`));for(const k of C.PAYMENTS)box.append(el("p",`${k}：${raw.payments[k]??"未讀出"}`));for(const error of check.errors)box.append(el("p",error,"error"));for(const warning of check.warnings)box.append(el("p",warning,"warning"));box.append(el("p","待人工確認表頭與收款；此頁只供測試，不代表已保存訂單。","warning"));$("results").append(box);}for(const [i,item] of order.items.entries()){
 const box=el("div","","item");box.append(el("h3",`第 ${raw.rows[i].row} 列`),el("p",`原貨號：${raw.rows[i].sku||"未填"}｜紙本品名：${item.paperName||"未讀出"}`),el("p",`採用貨號：${item.sku||"待查"}｜正式品名：${item.name||"尚未對應"}｜${item.color||"缺顏色"}｜${item.size||"缺尺碼"}`));
 if(item.matchStatus==="name_auto")box.append(el("p","品名唯一反查已帶入貨號，待人工確認","warning"));else if(!item.sku){const reverse=C.reverseProduct(master,item);box.append(el("p",reverse.status==="ambiguous"?`有 ${reverse.matches.length} 個候選，未自動帶入` : "品名不足或無唯一對應，未猜貨號","warning"));}
 box.append(el("p",`數量：${item.quantity??"待確認"}｜成交單價：${item.unitPrice===""?"待確認／組合採總價":item.unitPrice}｜銷別：${item.saleType||"待確認"}${item.recognitionUncertain?"｜辨識不確定，須覆核":""}`));$("results").append(box);
 }
 for(const group of order.priceGroups){const rows=raw.sharedPrices[order.priceGroups.indexOf(group)].rows;$("results").append(el("p",`第 ${rows.join("、")} 列共用 ${group.amount===""?"待確認":group.amount} 元；只記一次，各列單價留空，整組只計一次，不需分攤。`,"warning"));}
 for(const warning of raw.warnings)$("results").append(el("p",warning,"warning"));
 $("summary").textContent=`${provenance}：${raw.rows.length}列；${order.items.filter(x=>x.matchStatus==="name_auto").length}列由品名反查；${order.priceGroups.length}組跨列金額。尚未保存為公司訂單。`;
 if(expected){const m=evaluateExtraction(raw,expected);$("metrics").textContent=`標準 ${m.expectedRows}列／辨識 ${m.actualRows}列；${Object.entries(m.fields).map(([k,v])=>`${k} ${v.correct}/${v.total}`).join("；")}；跨列組合 ${m.sharedPricesEqual?"一致":"不一致"}${m.fullFields?`；完整欄位 ${Object.values(m.fullFields).filter(Boolean).length}/${Object.keys(m.fullFields).length}`:""}。只比較本次樣本，不代表已達上線標準。`;}
}
$("master").onchange=()=>run(async()=>{const file=$("master").files[0];if(!file)return;master=C.parseMaster(XLSX.read(await file.arrayBuffer(),C.READ_OPTIONS),XLSX,`validation:${Date.now()}`);$("master-status").textContent=`已載入 ${master.count} 個貨號，主檔只在本機比對`;render();});
$("image").onchange=()=>run(async()=>{clearCrop();clearResults();syntheticImage="";image?.close();image=null;const file=$("image").files[0];if(!file)return;if(!["image/jpeg","image/png"].includes(file.type)||file.size>20000000)throw Error("請選20MB內JPEG或PNG");image=await createImageBitmap(file);if(image.width*image.height>40000000){image.close();image=null;throw Error("圖片尺寸過大，請縮小");}status("照片已在本機開啟，請產生完整預覽；尚未傳出");});
for(const id of ["left","right","top","bottom"])$(id).oninput=()=>{clearCrop();clearResults();};
$("crop").onclick=()=>run(()=>{if(!image)throw Error("請先選照片");clearCrop();clearResults();const [left,right,top,bottom]=["left","right","top","bottom"].map(id=>$(id).value===""?NaN:Number($(id).value));if(![left,right,top,bottom].every(Number.isFinite)||left<0||right>100||top<0||bottom>100||left>=right||top>=bottom)throw Error("請輸入有效裁切範圍");prepared=prepareImageInput(image,{left,right,top,bottom,full:mode()==="full"});cropData=prepared.preview;$("crop-preview").src=cropData;$("crop-preview").hidden=false;status(mode()==="full"?`完整單已準備：全單預覽＋3張重疊細節，細節寬 ${prepared.plan.width} 像素；同一次API請求，圖片用量較高。請確認全為虛構個資後送出。`:"請確認商品區無個資後送出；已保留較高解析度。");});
$("deidentified").onchange=controls;$("synthetic-confirmed").onchange=controls;
$("mode").onchange=()=>{clearCrop();clearResults();expected=null;$("expected").value="";$("table-consent").hidden=mode()==="full";$("full-consent").hidden=mode()!=="full";$("left").value="0";$("right").value="100";for(const id of ["left","right","top","bottom"])$(id).parentElement.hidden=mode()==="full";$("crop").textContent=mode()==="full"?"產生／更新完整單預覽":"產生／更新商品區預覽";$("top").value=mode()==="full"?"0":"28";$("bottom").value=mode()==="full"?"100":"72";$("recognize").textContent=mode()==="full"?"傳送虛構完整單至 OpenAI 辨識":"傳送商品區至 OpenAI 辨識";$("mode-help").textContent=mode()==="full"?"完整單模式只准虛構客戶資料，請包含表頭、商品、付款區。已確認個資全為虛構的原測試照片可以使用；勿傳真實客戶資料。":"目前只測商品區，不得包含真實客戶表頭。";};
for(const id of ["expected-store","existing-numbers"])$(id).oninput=render;
$("synthetic-image").onclick=()=>run(async()=>{image?.close();const canvas=renderSyntheticForm();syntheticImage=canvas.toDataURL("image/png");image=await createImageBitmap(canvas);$("mode").value="full";$("mode").onchange();status("已產生全為虛構資料的印刷字完整單。請產生預覽再確認送出；手寫效果需另填虛構單測試。");});
$("download-image").onclick=()=>run(()=>{const a=document.createElement("a");a.href=syntheticImage;a.download="虛構完整訂單_印刷字測試.png";a.click();});
$("recognize").onclick=()=>run(async()=>{if(!cropData||!consent())throw Error("請先確認去識別化預覽");clearResults();status("正在傳送已確認的預覽至OpenAI；影像辨識可能需要數分鐘，請勿重複操作…");const response=await fetch("/api/store-orders-validation/recognize",{method:"POST",headers:{"Content-Type":"application/json","X-Store-Orders-Version":C.VERSION},body:JSON.stringify(mode()==="full"?{image:prepared.image,detailImages:prepared.detailImages,mode:"full",syntheticHeaderConfirmed:true}:{image:prepared.image,deidentifiedConfirmed:true})});const data=await response.json();if(!response.ok)throw Error(data.error||"辨識失敗");raw=validateExtraction(data.extraction);recognition=data.recognition||null;provenance=`OpenAI API 實測（${data.model}）`;render();status(`辨識已回傳，請逐列核對。${data.usage?`輸入token ${data.usage.input_tokens}／輸出token ${data.usage.output_tokens}`:""}`);});
$("synthetic").onclick=()=>run(()=>{recognition=null;if(mode()==="full"){raw=syntheticFullOrder();provenance="虛構完整單案例（不是AI實測）";render();status("已載入虛構完整單資料，未呼叫AI");return;}raw={rows:[{row:1,sku:"SAMPLE01",paperName:"測試床包",quantity:1,unitPrice:null,saleType:"銷貨",gift:false,uncertain:false},{row:2,sku:"SAMPLE02",paperName:"測試被套",quantity:1,unitPrice:null,saleType:"訂貨",gift:false,uncertain:false},{row:3,sku:"",paperName:"測試香氛噴霧",quantity:1,unitPrice:0,saleType:"銷貨",gift:true,uncertain:false}],sharedPrices:[{rows:[1,2],amount:300}],warnings:["合成資料，不是照片辨識；第3列故意漏貨號，載入含此品名的主檔可測反查。"]};provenance="合成規則案例（不是AI實測）";render();status("已載入合成規則案例，未呼叫AI");});
for(const [id,isExpected] of [["result-file",false],["expected",true]])$(id).onchange=()=>run(async()=>{const file=$(id).files[0];if(!file)return;if(file.size>1000000)throw Error("JSON檔案過大");const value=validateExtraction(JSON.parse(await file.text()));if((mode()==="full")!==Object.hasOwn(value,"header"))throw Error("結果模式不同，請先選擇對應測試範圍");if(isExpected)expected=value;else{raw=value;recognition=null;provenance="手動載入結果（來源未驗證）";}render();});
$("download").textContent="下載原始辨識 JSON（不含人工修正）";
$("download").onclick=()=>run(()=>{if(!raw)throw Error("尚無辨識結果");const blob=new Blob([JSON.stringify(raw,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=raw.header?"虛構完整單辨識結果.json":"去識別化商品辨識結果.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);});
$("reload-version").onclick=()=>location.assign(`/store-orders/validation.html?deploy=${encodeURIComponent(guard.current||C.VERSION)}&reload=${Date.now()}`);
async function update(){await guard.check();controls();}window.addEventListener("focus",update);setInterval(update,60000);
await update();try{const r=await fetch("/api/store-orders-validation/config",{cache:"no-store"});if(r.ok){config=await r.json();if(config.version!==C.VERSION)config=null;}}catch{/* regular static site cannot enable API */}
$("mode").onchange();
$("api-status").textContent=config?.ready?`本機API已設定：OpenAI／${config.model}，尚未送出圖片` : "本機OpenAI API尚未就緒；請使用專用本機伺服器並設定金鑰與模型。仍可測試合成案例、載入主檔及預覽裁切。";controls();
